#[verus::spec]
fn good_count(digit: char) -> u32 {
    match digit {
        '0' => 2,
        '1' => 7,
        '2' => 2,
        '3' => 3,
        '4' => 3,
        '5' => 4,
        '6' => 2,
        '7' => 5,
        '8' => 1,
        '9' => 2,
        _ => 0, // This case should not occur given the problem constraints
    }
}

#[verus::spec]
fn to_string(n: u32) -> Vec<char> {
    if n == 0 {
        return vec!['0'];
    }
    let mut result = Vec::new();
    let mut num = n;
    while num > 0 {
        let digit = (num % 10) as u8 as char;
        result.push(digit);
        num /= 10;
    }
    result.reverse();
    result
}

#[verus::spec]
fn solve(input: Vec<char>) -> Vec<char> {
    // Requires that the input has at least 2 characters
    requires(input.len() >= 2);
    // Ensure that the first two characters are digits
    requires(input[0].is_ascii_digit());
    requires(input[1].is_ascii_digit());

    // Compute the good counts
    let count1 = good_count(input[0]);
    let count2 = good_count(input[1]);
    
    // Compute the product
    let product = count1 * count2;

    // Ensure the product is within the specified range
    ensures(product >= 1 && product <= 49);

    // Convert the product to a string representation
    let mut result = to_string(product);
    result.push('\n'); // Append the newline character

    // Ensure the output contains only digit characters and a newline
    ensures(result.len() > 0);
    ensures(result[result.len() - 1] == '\n');

    result
}